/**
 * Common Utils function for set interval
 * @param {*} callback 
 * @param {*} interval 
 */
function IntervalTimer(callback, interval) {
  let timerId;
  let startTime;
  let remaining = 0;
  let state = 0; //  0 = idle, 1 = running, 2 = paused, 3= resumed

  this.pause = () => {
    if (state !== 1) return;
    remaining = interval - (new Date() - startTime);
    window.clearInterval(timerId);
    state = 2;
  };
  this.resume = () => {
    if (state !== 2) return;
    state = 3;
    window.setTimeout(this.timeoutCallback, remaining);
  };
  this.timeoutCallback = () => {
    if (state !== 3) return;
    callback();
    startTime = new Date();
    timerId = window.setInterval(callback, interval);
    state = 1;
  };
  this.clearInterval = () => {
    window.clearInterval(timerId);
  };
  startTime = new Date();
  timerId = window.setInterval(callback, interval);
  state = 1;
}
